begin;
create temporary table ml(actor uuid,other_actor uuid,wid uuid,sid uuid,other_site uuid,mid uuid,attempt uuid,d jsonb);
insert into ml values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),'{"schema":"private-media-descriptor-v1","mime":"image/png","bytes":1024,"width":1000,"height":1500,"sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","alt":"Background","origin":"user-upload","rights":{"basis":"own-work","evidence":"My work","attested":true}}');
insert into auth.users(id) select actor from ml union all select other_actor from ml;
insert into public.bizoveya_workspaces(id,owner_id,name) select wid,actor,'Lifecycle fixture' from ml;
insert into public.bizoveya_memberships(workspace_id,user_id,role) select wid,actor,'owner' from ml union all select wid,other_actor,'viewer' from ml;
insert into public.bizoveya_sites(id,workspace_id,name,mode,kind,status,created_by) select sid,wid,'Media A','native_business','business','active',actor from ml union all select other_site,wid,'Media B','native_business','business','active',actor from ml;
create function pg_temp.expect_lifecycle(q text,n text) returns void language plpgsql as $$begin begin execute q;exception when others then if strpos(sqlerrm,n)>0 then return;end if;raise;end;raise exception 'Expected %',n;end;$$;
do $$begin execute format('grant usage on schema %I to authenticated,service_role',(select nspname from pg_namespace where oid=pg_my_temp_schema()));end;$$;grant all on ml to authenticated,service_role;
set local role authenticated;
select pg_temp.expect_lifecycle(format('select public.bz_prepare_media_upload(%L,%L,%L,%L,%L,0,%L::jsonb)',actor,wid,sid,attempt,mid,d),'permission denied') from ml;
reset role;set local role service_role;select set_config('request.jwt.claim.role','service_role',true);
select pg_temp.expect_lifecycle(format('select public.bz_prepare_media_upload(%L,%L,%L,%L,%L,0,%L::jsonb)',other_actor,wid,sid,attempt,mid,d),'bz_forbidden') from ml;
select public.bz_admit_media_processing(actor,wid,sid) from ml;
select public.bz_prepare_media_upload(actor,wid,sid,attempt,mid,0,d) from ml;
select public.bz_prepare_media_upload(actor,wid,sid,attempt,mid,0,d) from ml;
select pg_temp.expect_lifecycle(format('select public.bz_prepare_media_upload(%L,%L,%L,%L,%L,0,%L::jsonb)',actor,wid,sid,gen_random_uuid(),mid,d),'bz_upload_busy') from ml;
select public.bz_commit_media_upload(actor,wid,sid,attempt) from ml;
select public.bz_commit_media_upload(actor,wid,sid,attempt) from ml;
select public.bz_prepare_media_upload(actor,wid,sid,attempt,mid,0,d) from ml;
select public.bz_private_media_object(actor,wid,sid,mid,1) from ml;
select pg_temp.expect_lifecycle(format('select public.bz_private_media_object(%L,%L,%L,%L,1)',actor,wid,other_site,mid),'bz_media_unavailable') from ml;
do $$declare f record;a uuid:=gen_random_uuid();m uuid:=gen_random_uuid();begin select * into f from ml;perform public.bz_prepare_media_upload(f.actor,f.wid,f.sid,a,m,0,f.d);end;$$;
reset role;
do $$begin if (select count(*) from bizoveya_private.private_media_versions where media_id=(select mid from ml))<>1 or (select admissions from bizoveya_private.media_upload_rate where actor_id=(select actor from ml))<>2 then raise exception 'Idempotency or rate accounting failed';end if;end;$$;
update bizoveya_private.media_upload_attempts set created_at=clock_timestamp()-interval '11 minutes' where actor_id=(select actor from ml);
update bizoveya_private.media_upload_rate set admissions=12 where actor_id=(select actor from ml);
update bizoveya_private.media_upload_rate set processing=36 where actor_id=(select actor from ml);
set local role service_role;
select pg_temp.expect_lifecycle(format('select public.bz_admit_media_processing(%L,%L,%L)',actor,wid,sid),'bz_upload_processing_limit') from ml;
select pg_temp.expect_lifecycle(format('select public.bz_prepare_media_upload(%L,%L,%L,%L,%L,0,%L::jsonb)',actor,wid,sid,gen_random_uuid(),gen_random_uuid(),d),'bz_upload_rate_limit') from ml;
do $$declare f record;r jsonb;begin select * into f from ml;select public.bz_claim_media_cleanup(f.actor,f.wid,f.sid) into r;if jsonb_array_length(r)<>1 then raise exception 'Cleanup selected saved bytes or missed orphan';end if;perform pg_temp.expect_lifecycle(format('select public.bz_commit_media_upload(%L,%L,%L,%L)',f.actor,f.wid,f.sid,r#>>'{0,id}'),'bz_upload_expired');perform public.bz_finish_media_cleanup(f.actor,f.wid,f.sid,(r#>>'{0,id}')::uuid);end;$$;
reset role;
delete from auth.users where id=(select actor from ml);
set local role service_role;
do $$declare r jsonb;begin select public.bz_claim_media_cleanup_global() into r;if jsonb_array_length(r)<>1 then raise exception 'Deleted-account byte orphan missed';end if;perform public.bz_finish_media_cleanup_global((r#>>'{0,id}')::uuid);end;$$;
reset role;
do $$begin if exists(select 1 from bizoveya_private.media_upload_attempts where actor_id=(select actor from ml)) then raise exception 'Cleanup ledger retained completed orphan';end if;end;$$;
rollback;
